def relabelEquiv {R : Type*} [Semiring R] {n : ℕ}
    (e : GridState n ≃ GridState n) :
    GridChain R n ≃ₗ[R] GridChain R n

theorem relabelEquiv_single {R : Type*} [Semiring R] {n : ℕ}
    (e : GridState n ≃ GridState n) (x : GridState n) (a : R) :
    relabelEquiv e (Finsupp.single x a) = Finsupp.single (e x) a

theorem relabelEquiv_apply {R : Type*} [Semiring R] {n : ℕ}
    (e : GridState n ≃ GridState n)
    (f : GridChain R n) (y : GridState n) : relabelEquiv e f y = f (e.symm y)

theorem relabelEquiv_symm {R : Type*} [Semiring R] {n : ℕ}
    (e : GridState n ≃ GridState n) :
    (relabelEquiv (R := R) e).symm = relabelEquiv e.symm

theorem exists_swapColumns_of_fullyBlockedDifferentialOnGenerator_ne_zero {x y : GridState n}
    (h : G.fullyBlockedDifferentialOnGenerator x y ≠ 0) :
    ∃ a b : Fin n, a ≠ b ∧ y = x.swapColumns a b

theorem sym2_mk_eq_of_swapColumns_swapColumns_eq_self (x : GridState n) {a b c d : Fin n}
    (hab : a ≠ b) (hcd : c ≠ d) (h : (x.swapColumns a b).swapColumns c d = x) :
    s(a, b) = s(c, d)

theorem swapColumns_swapColumns_eq_self_iff_sym2_mk_eq (x : GridState n) {a b c d : Fin n}
    (hab : a ≠ b) (hcd : c ≠ d) :
    (x.swapColumns a b).swapColumns c d = x ↔ s(a, b) = s(c, d)

theorem J_singleton_singleton_of_isSouthWest_or_isSouthWest {p q : Fin n × Fin n}
    (h : IsSouthWest p q ∨ IsSouthWest q p) :
    GridPoint.J {p} {q} = (1 : ℚ) / 2

theorem mem_target_pointSet_iff_of_ne {p : Fin n × Fin n}
    (hleft : p.1 ≠ R.left) (hright : p.1 ≠ R.right) :
    p ∈ y.pointSet ↔ p ∈ x.pointSet

theorem transpose_toGridRectangle (R : GridRectangleBetween x y) :
    R.transpose.toGridRectangle =
      { left := R.bottom, right := R.top, bottom := R.left, top := R.right }

theorem swapSides_toGridRectangle_aux (R : GridRectangleBetween x y) :
    R.swapSides.toGridRectangle =
      { left := R.right, right := R.left, bottom := R.top, top := R.bottom }

theorem swapSides_toGridRectangle (R : GridRectangleBetween x y) :
    R.swapSides.toGridRectangle =
      { left := R.right, right := R.left, bottom := R.top, top := R.bottom }
